def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    fit_mask = bins >= item
    remaining_after = bins - item
    target_remaining = bins / 2
    return np.where(fit_mask, -((remaining_after - target_remaining) ** 2), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    import numpy as np
    fit_mask = bins >= item
    remaining_after = bins - item
    avg_remaining = np.mean(remaining_after[fit_mask]) if np.any(fit_mask) else 0
    return np.where(fit_mask, -np.abs(remaining_after - avg_remaining), -np.inf)
